The following Terraform configuration creates an AWS RDS MySQL database instance that skips the final snapshot when destroyed. It includes a dedicated VPC, two private subnets in separate Availability Zones, a DB subnet group, a security group allowing MySQL access from within the VPC, and a randomly generated master password.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

